(function () {
// Zusatzfälle nach Klausurgewichtung, je 6 Antworten
const W=(window.WPRK_LONG=window.WPRK_LONG||[]);
const L=[{"topic": "lst", "sv": "Händler H soll dem Kunden K ein Sofa „in der 12. Kalenderwoche“ liefern. Die Woche verstreicht ohne Lieferung. K mahnt nicht. Am Montag der 13. Woche mietet K für 200 € ein Ersatzsofa für eine Feier.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["H ist nicht in Verzug, weil K nicht gemahnt hat (§ 286 I).", "Falsch. Eine kalendermäßig bestimmte Leistungszeit macht die Mahnung entbehrlich (§ 286 II Nr. 1)."], ["H ist erst nach Ablauf von 30 Tagen in Verzug (§ 286 III).", "Falsch. § 286 III betrifft Entgeltforderungen."], ["H ist nicht in Verzug, weil eine Kalenderwoche keine kalendermäßige Bestimmung ist.", "Falsch. Auch eine bestimmte Kalenderwoche genügt."], ["H ist mit Ablauf der 12. Kalenderwoche ohne Mahnung in Verzug (§ 286 II Nr. 1).", "Richtig. Leistungszeit nach dem Kalender bestimmt."], ["K kann die 200 € nur als Schadensersatz statt der Leistung nach Fristsetzung verlangen.", "Falsch. Die Mietkosten sind Verzögerungsschaden (§§ 280 I, II, 286)."], ["H ist in Verzug, haftet aber nur, wenn er die Verspätung grob fahrlässig verursacht hat.", "Falsch. Jede Fahrlässigkeit genügt (§§ 286 IV, 276)."]], "id": "P2-lst1-0"}, {"topic": "lst", "sv": "Handwerker H soll „zehn Tage nach Abruf“ bei Kunde K eine Treppe einbauen. K ruft am 1. März ab. H kommt bis zum 15. März nicht.", "q": "Seit wann ist H ohne Mahnung in Verzug?", "c": 1, "o": [["Gar nicht; ohne Mahnung tritt nie Verzug ein.", "Falsch. § 286 II enthält Ausnahmen."], ["Seit Ablauf des 11. März; eine Mahnung war entbehrlich.", "Richtig. Zehn Tage ab Abruf. (§ 286 II Nr. 2)"], ["Seit dem 1. März, weil der Abruf selbst eine Mahnung ist.", "Falsch. Der Abruf macht die Leistung erst fällig."], ["Seit dem 31. März, 30 Tage nach dem Abruf (§ 286 III).", "Falsch. § 286 III betrifft Entgeltforderungen."], ["Erst ab Zugang einer schriftlichen Mahnung, weil Werkverträge nur schriftlich gemahnt werden können.", "Falsch. Eine Mahnung ist formfrei; hier ist sie entbehrlich."], ["Seit dem 15. März, weil H erst dann erkennbar säumig ist.", "Falsch. Maßgeblich ist der Ablauf der Frist."]], "id": "P2-lst1-1"}, {"topic": "lst", "sv": "Lieferant L schuldet der Kundin K bis 1. April die Lieferung von Saatgut. Am 20. März schreibt L: „Wir werden überhaupt nicht liefern, wir haben die Produktion eingestellt.“ K kauft sofort anderswo zum höheren Preis.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["K kann die Mehrkosten ohne Fristsetzung verlangen (§ 281 II).", "Richtig. Frist entbehrlich, auch schon vor Fälligkeit."], ["K muss bis zum 1. April warten und dann eine Frist setzen.", "Falsch. Bei ernsthafter und endgültiger Verweigerung ist die Frist entbehrlich."], ["K hat keinen Anspruch, weil L vor Fälligkeit noch nicht in Verzug war.", "Falsch. Die endgültige Verweigerung ist eine Pflichtverletzung."], ["K kann nur zurücktreten, Schadensersatz bekommt sie nicht.", "Falsch. Beides ist möglich (§ 325)."], ["K kann die Mehrkosten nur verlangen, wenn L die Produktionseinstellung verschuldet hat.", "Falsch. Das Vertretenmüssen wird vermutet (§ 280 I 2)."], ["K muss L zuerst mahnen, damit die Verweigerung wirksam wird.", "Falsch. Eine Mahnung ist sinnlos und entbehrlich."]], "id": "P2-lst1-2"}, {"topic": "lst", "sv": "Hotelier H bestellt bei Bäcker B für die Hochzeitsfeier am Samstag eine Hochzeitstorte. B vergisst die Bestellung und kann erst am Montag liefern.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["H muss B eine Nachfrist setzen, bevor er Schadensersatz verlangen kann.", "Falsch. Bei Unmöglichkeit ist eine Frist sinnlos."], ["Es liegt ein relatives Fixgeschäft vor; H kann ohne Frist zurücktreten, bleibt aber zur Abnahme bereit.", "Falsch. Eine Hochzeitstorte nach der Feier ist wertlos: absolutes Fixgeschäft."], ["B kann am Montag liefern, weil Verspätung kein Fall der Unmöglichkeit ist.", "Falsch. Beim absoluten Fixgeschäft führt Zeitablauf zur Unmöglichkeit."], ["H muss die Torte am Montag abnehmen und kann nur mindern.", "Falsch. Die Leistung ist unmöglich; Minderung passt nicht."], ["Absolutes Fixgeschäft: Die Leistung ist unmöglich geworden; B schuldet bei Vertretenmüssen Schadensersatz.", "Richtig. Vergessen ist fahrlässig. (§§ 275 I, 280 I, III, 283)"], ["B schuldet nichts, weil er die Bestellung nicht vorsätzlich vergessen hat.", "Falsch. Fahrlässigkeit genügt (§ 276 I)."]], "id": "P2-lst1-3"}, {"topic": "lst", "sv": "Händler H verkauft dem Gartencenter G 500 Weihnachtssterne, Lieferung „fix am 1. Dezember“, damit G sie in der Adventszeit verkaufen kann. H liefert erst am 8. Dezember an. G lehnt ab und erklärt sofort den Rücktritt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Der Rücktritt ist unwirksam, weil G zuerst eine Nachfrist setzen muss.", "Falsch. Beim relativen Fixgeschäft ist die Frist entbehrlich (§ 323 II Nr. 2)."], ["Die Leistung ist unmöglich geworden, G muss nicht zurücktreten.", "Falsch. Weihnachtssterne sind auch nach dem 1. Dezember noch verkäuflich: relatives Fixgeschäft."], ["Der Rücktritt ist ohne Fristsetzung wirksam, weil ein relatives Fixgeschäft vorliegt.", "Richtig. Termin war erkennbar wesentlich. (§ 323 II Nr. 2)"], ["Der Rücktritt ist nur wirksam, wenn H die Verspätung verschuldet hat.", "Falsch. Der Rücktritt ist verschuldensunabhängig."], ["G kann nur Schadensersatz verlangen, ein Rücktritt ist beim Fixgeschäft ausgeschlossen.", "Falsch. Gerade beim relativen Fixgeschäft ist der Rücktritt erleichtert."], ["Der Rücktritt ist unwirksam, weil „fix“ nur eine Floskel ohne rechtliche Bedeutung ist.", "Falsch. „Fix“ mit Datum und erkennbarem Zweck begründet ein relatives Fixgeschäft."]], "id": "P2-lst1-4"}, {"topic": "lst", "sv": "V verkauft K einen bestimmten Oldtimer. Vor der Übergabe wird er bei V gestohlen; V trifft kein Verschulden. V erhält von seiner Diebstahlversicherung 30.000 €; der Kaufpreis betrug 25.000 €.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["K hat keinerlei Ansprüche, weil V den Diebstahl nicht zu vertreten hat.", "Falsch. § 285 gibt einen Anspruch auf das Surrogat."], ["K kann 30.000 € verlangen und muss nichts zahlen, weil V von der Leistung frei geworden ist.", "Falsch. Wer das Surrogat verlangt, bleibt zur Gegenleistung verpflichtet (§ 326 III)."], ["K kann nur 5.000 € verlangen, also die Differenz zum Kaufpreis.", "Falsch. Er kann das ganze Surrogat verlangen und schuldet den Preis."], ["V muss einen gleichwertigen Oldtimer beschaffen.", "Falsch. Stückschuld; Leistung unmöglich (§ 275 I)."], ["K kann die Versicherungsleistung nur verlangen, wenn er selbst versichert war.", "Falsch. Es geht um die Versicherung des V; § 285 erfasst sie."], ["K kann die 30.000 € von V verlangen, muss dann aber die 25.000 € zahlen (§§ 285, 326 III).", "Richtig. Stellvertretendes commodum; Gegenleistung bleibt geschuldet."]], "id": "P2-lst1-5"}, {"topic": "lst", "sv": "Opernsängerin S soll am 10. Mai im Theater des T auftreten. Am Morgen erkrankt ihr Kind lebensgefährlich; S bleibt im Krankenhaus. T verlangt Schadensersatz.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["S bleibt zur Leistung verpflichtet, weil die Leistung objektiv möglich ist.", "Falsch. § 275 III gibt ein Leistungsverweigerungsrecht bei persönlicher Leistung."], ["S wird nach § 275 I frei, weil niemand anderes ihre Rolle singen kann.", "Falsch. Es geht um Unzumutbarkeit (§ 275 III), nicht objektive Unmöglichkeit."], ["S kann verweigern (§ 275 III) und schuldet mangels Verschulden keinen Ersatz.", "Richtig. Persönliche Leistung, Unzumutbarkeit."], ["S schuldet Schadensersatz, weil sie die Leistung freiwillig verweigert hat.", "Falsch. Die Verweigerung ist berechtigt und nicht zu vertreten."], ["S kann die Leistung nur verweigern, wenn T zustimmt.", "Falsch. § 275 III ist eine Einrede; eine Zustimmung ist nicht nötig."], ["S kann verweigern, muss T aber die Hälfte der Gage als Entschädigung zahlen.", "Falsch. Eine solche Pflicht gibt es nicht; sie verliert nur die Gage (§ 326 I)."]], "id": "P2-lst1-6"}, {"topic": "lst", "sv": "V verkauft K ein Wochenendhaus. Bei Vertragsschluss war es, ohne dass V es wusste oder hätte wissen können, schon durch einen Brand zerstört.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Der Vertrag ist nichtig, weil die Leistung schon bei Vertragsschluss unmöglich war.", "Falsch. § 311a I: Der Vertrag bleibt wirksam."], ["V schuldet Schadensersatz statt der Leistung, weil er für anfängliche Unmöglichkeit immer haftet.", "Falsch. Nur bei Kenntnis oder fahrlässiger Unkenntnis (§ 311a II 2)."], ["K muss den Kaufpreis zahlen, weil die Gefahr mit Vertragsschluss übergegangen ist.", "Falsch. Die Gegenleistung entfällt (§ 326 I 1)."], ["Der Vertrag ist wirksam; V ist frei und schuldet keinen Schadensersatz (§ 311a II).", "Richtig. Anfängliche Unmöglichkeit ohne Kenntnis."], ["Der Vertrag ist schwebend unwirksam, bis das Haus wieder aufgebaut ist.", "Falsch. Eine solche Schwebe gibt es nicht."], ["V kann den Vertrag wegen Irrtums über den Zustand des Hauses anfechten und wird so frei.", "Falsch. § 311a regelt die Rechtsfolgen abschließend; einer Anfechtung bedarf es nicht."]], "id": "P2-lst1-7"}, {"topic": "lst", "sv": "Möbelhändler M soll dem Kunden K am 5. Juni zwischen 8 und 12 Uhr einen Schrank liefern. M klingelt um 10 Uhr, K ist nicht da. Auf der Rückfahrt wird der Schrank durch einen leicht fahrlässig verursachten Unfall des Fahrers zerstört.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["K muss nicht zahlen, weil M den Unfall fahrlässig verursacht hat.", "Falsch. Im Annahmeverzug haftet M nur für Vorsatz und grobe Fahrlässigkeit (§ 300 I)."], ["K muss zahlen; M ist frei, weil der Schrank im Annahmeverzug unterging.", "Richtig. Annahmeverzug, leichte Fahrlässigkeit. (§§ 300 I, 326 II 1 Alt. 2)"], ["M muss einen neuen Schrank liefern, weil K nicht in Annahmeverzug war.", "Falsch. M hat zur vereinbarten Zeit tatsächlich angeboten (§ 294)."], ["K muss zahlen, M muss aber einen neuen Schrank liefern.", "Falsch. M ist von der Leistungspflicht frei (§ 275 I)."], ["K muss nur zahlen, wenn er den Termin schuldhaft versäumt hat.", "Falsch. Annahmeverzug setzt kein Verschulden voraus."], ["K muss die Hälfte zahlen, weil beide den Untergang mitverursacht haben (§ 254).", "Falsch. Es gilt § 326 II 1 Alt. 2: voller Preis."]], "id": "P2-lst1-8"}, {"topic": "lst", "sv": "Schreiner S soll für K ein Regal „nach Absprache“ einbauen; ein Termin ist nicht vereinbart. S kommt unangekündigt am Dienstag um 9 Uhr, K ist bei der Arbeit. S verlangt 60 € Anfahrtskosten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["S bekommt die 60 €, weil K in Annahmeverzug war (§§ 293, 304).", "Falsch. Bei unbestimmter Leistungszeit führt eine vorübergehende Verhinderung ohne Ankündigung nicht zum Annahmeverzug (§ 299)."], ["S bekommt die 60 € als Schadensersatz, weil K seine Pflicht zur Mitwirkung verletzt hat.", "Falsch. Die Mitwirkung ist eine Obliegenheit; Schadensersatz scheidet aus."], ["S bekommt die 60 € nicht, weil Anfahrtskosten nie ersatzfähig sind.", "Falsch. Im Annahmeverzug sind Mehraufwendungen ersatzfähig (§ 304)."], ["S bekommt die 60 € nur zur Hälfte, weil beide den Termin hätten abstimmen müssen.", "Falsch. Es fehlt schon am Annahmeverzug."], ["S bekommt die 60 € nicht, weil K nicht in Annahmeverzug war.", "Richtig. Unbestimmte Leistungszeit, keine Ankündigung. (§ 299)"], ["S bekommt die 60 €, weil § 299 nur bei Kaufverträgen gilt.", "Falsch. §§ 293 ff. gelten für alle Schuldverhältnisse."]], "id": "P2-lst1-9"}, {"topic": "lst", "sv": "K hat mit Tischler T vereinbart, dass T am 20. Mai einen Einbauschrank liefert und einbaut. Am 18. Mai sagt K telefonisch: „Kommen Sie gar nicht erst, ich nehme den Schrank nicht.“ T bietet daraufhin schriftlich an, wie vereinbart zu liefern.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["K ist nicht in Annahmeverzug, weil T nicht tatsächlich mit dem Schrank erschienen ist.", "Falsch. Nach Ablehnung genügt ein wörtliches Angebot (§ 295 S. 1)."], ["K ist nur in Annahmeverzug, wenn er die Ablehnung schuldhaft erklärt hat.", "Falsch. Annahmeverzug ist verschuldensunabhängig."], ["K ist im Schuldnerverzug und muss Verzugszinsen auf den Werklohn zahlen.", "Falsch. Es geht um den Annahmeverzug; Verzugszinsen setzen Zahlungsverzug voraus."], ["T muss den Schrank trotzdem am 20. Mai tatsächlich anbieten, sonst entfällt jeder Anspruch.", "Falsch. Ein wörtliches Angebot genügt."], ["Die Ablehnung ist unwirksam, weil sie nur telefonisch erklärt wurde.", "Falsch. Sie ist formfrei."], ["K ist durch Ablehnung und wörtliches Angebot in Annahmeverzug geraten (§ 295).", "Richtig. Erklärte Annahmeverweigerung. (§§ 293, 295)"]], "id": "P2-lst1-10"}, {"topic": "lst", "sv": "Bäcker B schuldet dem Café C täglich 50 Brötchen (Gattungsschuld, Bringschuld). Am 3. Mai fährt der Fahrer pünktlich vor, das Café ist wegen eines Wasserschadens geschlossen und niemand öffnet. Auf der Rückfahrt verderben die Brötchen in einem langen Stau bei großer Hitze.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["C ist in Annahmeverzug; B muss nicht nachliefern und behält den Kaufpreis.", "Richtig. Tatsächliches Angebot zur rechten Zeit. (§§ 300 II, 326 II 1 Alt. 2)"], ["B muss erneut liefern, weil er Gattungsware schuldet.", "Falsch. Mit dem tatsächlichen Angebot und dem Annahmeverzug geht die Leistungsgefahr über (§ 300 II)."], ["C muss nicht zahlen, weil der Wasserschaden nicht von C verschuldet war.", "Falsch. Annahmeverzug setzt kein Verschulden voraus."], ["C muss nur zahlen, wenn B das Café vorher angerufen hat.", "Falsch. Bei bestimmter Leistungszeit ist keine Ankündigung nötig."], ["B schuldet Schadensersatz, weil die Brötchen auf seiner Rückfahrt verdorben sind.", "Falsch. Im Annahmeverzug haftet B nur für Vorsatz und grobe Fahrlässigkeit (§ 300 I); beides liegt nicht vor."], ["C muss nur die Hälfte zahlen, weil die Brötchen ohnehin vom Vortag waren.", "Falsch. Dafür fehlt jede Grundlage."]], "id": "P2-lst1-11"}, {"topic": "lst", "sv": "Dachdecker D soll beim Kunden K das Dach decken. Beim Hochtragen der Ziegel beschädigt D’s Geselle G fahrlässig das Auto des K in der Einfahrt.", "q": "Welche Ansprüche hat K wegen des Autos?", "c": 1, "o": [["K hat nur einen Anspruch gegen G aus § 823 I, nicht gegen D.", "Falsch. D haftet vertraglich für G (§ 278)."], ["K hat Ansprüche gegen D aus §§ 280 I, 241 II, 278 und gegen G aus § 823 I.", "Richtig. Schutzpflichtverletzung durch Erfüllungsgehilfen."], ["K hat gegen D nur einen Anspruch aus § 831, von dem D sich entlasten kann.", "Falsch. Vertraglich haftet D über § 278 ohne Entlastung."], ["K hat keinen Anspruch, weil das Auto nicht Gegenstand des Werkvertrags war.", "Falsch. Rücksichtnahmepflichten schützen auch andere Rechtsgüter (§ 241 II)."], ["K hat gegen D nur einen Anspruch, wenn er D vorher eine Frist gesetzt hat.", "Falsch. Schadensersatz neben der Leistung braucht keine Frist."], ["K hat gegen D nur einen Anspruch, wenn D den G nicht sorgfältig ausgewählt hat.", "Falsch. Das wäre der Maßstab des § 831."]], "id": "P2-lst1-12"}, {"topic": "lst", "sv": "Gärtner G pflegt für K seit Jahren den Garten. Beim Mähen beschädigt G jedes Mal Beete, obwohl K ihn mehrfach abgemahnt hat. K will den Vertrag nicht fortsetzen und einen anderen Gärtner beauftragen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["K kann nur Schadensersatz für die Beete verlangen, ein Lösungsrecht hat er nicht.", "Falsch. § 324 gibt ein Rücktrittsrecht."], ["K muss G eine Frist zur Nacherfüllung für die Beete setzen, bevor er sich lösen kann.", "Falsch. Bei Schutzpflichtverletzungen genügt nach § 314 II die erfolglose Abmahnung."], ["K kann nach § 324 mit Wirkung von Anfang an zurücktreten und alle bisherigen Zahlungen zurückverlangen.", "Falsch. Bei Dauerschuldverhältnissen tritt die Kündigung (§ 314) an die Stelle des Rücktritts; sie wirkt nur für die Zukunft."], ["K kann sich nur lösen, wenn der Vertrag eine Kündigungsklausel enthält.", "Falsch. Das Gesetz gibt das Recht zur Kündigung aus wichtigem Grund (§ 314)."], ["K muss den Vertrag bis zum Ende der Saison erfüllen und G dann ersetzen.", "Falsch. Eine solche Pflicht besteht nicht."], ["K kann den Vertrag aus wichtigem Grund kündigen, weil die Abmahnungen erfolglos blieben (§ 314).", "Richtig. Dauerschuldverhältnis: Kündigung statt Rücktritt; Abmahnung ist erfolgt (§ 314 II)."]], "id": "P2-lst1-13"}, {"topic": "lst", "sv": "Unternehmerin U verhandelt mit dem Vermieter V über die Anmietung von Büroräumen. V versichert mehrfach, der Vertrag werde „nur noch unterschrieben“, und bittet U, schon Möbel nach Maß zu bestellen. U bestellt für 8.000 €. Dann vermietet V ohne Grund an einen anderen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["U kann von V die Anmietung der Räume verlangen, weil die Einigung fast vollständig war.", "Falsch. Die c.i.c. begründet keinen Abschlusszwang."], ["U hat keinen Anspruch, weil jede Partei bis zur Unterschrift frei ist.", "Falsch. Nicht, wenn zurechenbar Vertrauen auf den sicheren Abschluss erweckt wurde."], ["U kann von V den Gewinn verlangen, den sie in den Räumen erzielt hätte.", "Falsch. Ersetzt wird das negative Interesse."], ["U hat einen Anspruch aus § 823 I wegen Verletzung ihres Vermögens.", "Falsch. Das Vermögen ist kein Rechtsgut des § 823 I."], ["U kann die 8.000 € als Vertrauensschaden verlangen (§§ 280 I, 311 II Nr. 1, 241 II).", "Richtig. Abbruch ohne triftigen Grund nach erwecktem Vertrauen."], ["U hat nur einen Anspruch, wenn V vorsätzlich getäuscht hat (§ 826).", "Falsch. Schon die c.i.c. greift; Vorsatz ist nicht nötig."]], "id": "P2-lst1-14"}, {"topic": "lst", "sv": "Verbraucherin V lässt beim Handwerker H die Heizung reparieren. Die Rechnung über 900 € geht ihr am 2. Mai zu; sie enthält den Hinweis: „Zahlbar binnen 30 Tagen; danach geraten Sie ohne Mahnung in Verzug.“ V zahlt nicht.", "q": "Ab wann ist V in Verzug?", "c": 3, "o": [["Gar nicht, solange H sie nicht mahnt.", "Falsch. § 286 III macht die Mahnung bei Entgeltforderungen entbehrlich."], ["Ab dem 2. Mai, weil die Rechnung zugleich eine Mahnung ist.", "Falsch. Die Rechnung begründet die Fälligkeit, keine Mahnung."], ["Erst 60 Tage nach Zugang, weil Verbraucher eine doppelte Frist haben.", "Falsch. Eine solche Verdopplung gibt es nicht."], ["30 Tage nach Zugang der Rechnung, weil diese V darauf hinweist.", "Richtig. Hinweis in der Rechnung vorhanden. (§ 286 III 1)"], ["30 Tage nach Zugang, aber nur, wenn die Rechnung per Einschreiben kam.", "Falsch. Es kommt nur auf den Zugang an."], ["Ab dem 2. Mai, weil Handwerkerleistungen sofort fällig und mahnungsfrei sind.", "Falsch. Eine solche Sonderregel gibt es nicht."]], "id": "P2-lst2-0"}, {"topic": "lst", "sv": "Großhändler G liefert dem Kaufmann K Waren für 10.000 €, zahlbar bis 31. März. K zahlt erst am 30. April. Der Basiszinssatz beträgt 2 %.", "q": "Welche Verzugszinsen und Pauschale kann G verlangen?", "c": 2, "o": [["Zinsen von 7 % (5 Punkte über dem Basiszinssatz), keine Pauschale.", "Falsch. Ohne Verbraucherbeteiligung gelten 9 Punkte, und die Pauschale fällt an (§ 288 II, V)."], ["Keine Zinsen, weil G nicht gemahnt hat.", "Falsch. Kalendermäßig bestimmte Leistungszeit (§ 286 II Nr. 1)."], ["Zinsen von 11 % (9 Punkte über Basiszins) für April und 40 € Pauschale.", "Richtig. Entgeltforderung, kein Verbraucher beteiligt. (§ 288 II, V)"], ["Zinsen von 9 % insgesamt, weil der gesetzliche Zinssatz unter Kaufleuten 9 % beträgt.", "Falsch. Es sind 9 Prozentpunkte über dem Basiszinssatz, also 11 %."], ["Zinsen von 11 % erst ab Zugang einer Mahnung, dazu 40 €.", "Falsch. Verzug trat schon mit Ablauf des 31. März ein."], ["Nur die Pauschale von 40 €, weil die Zinsen in ihr enthalten sind.", "Falsch. Zinsen und Pauschale bestehen nebeneinander; die Pauschale wird nur auf Rechtsverfolgungskosten angerechnet."]], "id": "P2-lst2-1"}, {"topic": "lst", "sv": "V soll K am 1. Juni ein Gemälde liefern, liefert aber nicht. Am 10. Juni wird das Bild bei V durch einen Blitzschlag zerstört. K hätte es bei pünktlicher Lieferung in seiner Wohnung aufgehängt, die von dem Unwetter verschont blieb.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["V haftet nicht, weil ein Blitzschlag höhere Gewalt ist.", "Falsch. Im Verzug haftet der Schuldner auch für Zufall (§ 287 S. 2)."], ["V haftet nur, wenn er den Blitzschlag hätte vorhersehen können.", "Falsch. § 287 S. 2 verlangt kein Verschulden."], ["K muss den Kaufpreis zahlen, weil die Gefahr mit dem Verzug auf ihn übergegangen ist.", "Falsch. Der Verzug des Schuldners verschiebt die Gefahr nicht auf den Gläubiger."], ["V haftet nicht, weil der Verzug durch den Blitzschlag rückwirkend entfallen ist.", "Falsch. Einen solchen Rechtssatz gibt es nicht."], ["V haftet für den Untergang, weil er im Verzug auch für Zufall einsteht (§ 287 S. 2).", "Richtig. Der Schaden wäre bei rechtzeitiger Leistung nicht eingetreten."], ["V haftet nur zur Hälfte, weil der Blitzschlag niemandem zuzurechnen ist.", "Falsch. § 287 S. 2 ordnet die volle Haftung an."]], "id": "P2-lst2-2"}, {"topic": "lst", "sv": "Spediteur S soll dem K bis 1. Juli eine Maschine liefern. Er liefert nicht. K setzt am 5. Juli eine Frist von nur drei Tagen; angemessen wären zwei Wochen. Am 12. Juli kauft K eine Ersatzmaschine für 2.000 € mehr. S liefert am 15. Juli.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["K kann die 2.000 € nicht verlangen, weil beim Deckungskauf die Frist noch nicht abgelaufen war.", "Richtig. Zu kurze Frist setzt angemessene in Gang (19. Juli)."], ["K kann die 2.000 € verlangen, weil die gesetzte Frist am 8. Juli abgelaufen war.", "Falsch. Eine zu kurze Frist setzt nur eine angemessene in Gang."], ["K kann die 2.000 € verlangen, weil eine zu kurze Frist unwirksam ist und dann gar keine Frist nötig war.", "Falsch. Die Frist bleibt erforderlich, sie verlängert sich nur."], ["K kann die 2.000 € als Verzögerungsschaden ohne Frist verlangen.", "Falsch. Mehrkosten des Deckungskaufs sind Schadensersatz statt der Leistung (§ 281)."], ["K kann die 2.000 € verlangen, muss aber die Maschine von S zusätzlich abnehmen.", "Falsch. K hat schon keinen Anspruch auf die 2.000 €."], ["K kann nichts verlangen, weil S am 15. Juli geliefert hat und damit erfüllt ist.", "Falsch. Ein Verzögerungsschaden bliebe möglich; nur die 2.000 € scheitern an der Frist."]], "id": "P2-lst2-3"}, {"topic": "lst", "sv": "Hersteller H soll dem Kaufmann K 100 Gartenstühle liefern (Gattungsschuld). H’s Lager brennt ab; die Stühle sind aber bei anderen Großhändlern ohne Weiteres erhältlich. H verweigert die Lieferung, weil ihn kein Verschulden treffe.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["H ist frei, weil sein ganzer Vorrat untergegangen ist (§ 275 I).", "Falsch. Ohne Beschränkung auf den eigenen Vorrat bleibt die Gattung lieferbar."], ["H ist frei, weil ihn am Brand kein Verschulden trifft.", "Falsch. Die Leistung ist nicht unmöglich; Verschulden ist für § 275 I unerheblich."], ["H muss nur zum ursprünglichen Einkaufspreis beschaffen; Mehrkosten trägt K.", "Falsch. Das Beschaffungsrisiko trägt H."], ["H kann nach § 313 eine Preisanpassung verlangen, weil der Brand die Geschäftsgrundlage zerstört hat.", "Falsch. Das Beschaffungsrisiko fällt in H’s Sphäre."], ["H ist frei, kann aber nach § 326 II den Kaufpreis verlangen.", "Falsch. H ist schon nicht frei."], ["H bleibt zur Lieferung verpflichtet und haftet bei Nichtlieferung, weil er das Beschaffungsrisiko trägt.", "Richtig. Gattungsschuld, Gattung nicht untergegangen. (§ 276 I)"]], "id": "P2-lst2-4"}, {"topic": "lst", "sv": "Landwirt L verkauft der Mühle M „20 Tonnen Weizen aus meiner diesjährigen Ernte“. Ein Hagelsturm vernichtet die gesamte Ernte. Am Markt wäre Weizen erhältlich.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["L muss den Weizen am Markt kaufen und liefern, weil Weizen Gattungsware ist.", "Falsch. Die Schuld ist auf die eigene Ernte beschränkt (Vorratsschuld)."], ["L wird frei, M muss nicht zahlen, und Schadensersatz schuldet L nicht.", "Richtig. Beschränkte Gattungsschuld, ganzer Vorrat untergegangen, kein Vertretenmüssen. (§§ 275 I, 326 I 1)"], ["L wird frei, M muss aber den Kaufpreis zahlen.", "Falsch. Die Gegenleistung entfällt (§ 326 I 1)."], ["L muss Schadensersatz leisten, weil er das Beschaffungsrisiko übernommen hat.", "Falsch. Ein Beschaffungsrisiko über die eigene Ernte hinaus hat er nicht übernommen."], ["L wird nur frei, wenn er sich ausdrücklich auf § 275 II beruft.", "Falsch. Bei Untergang des ganzen Vorrats greift § 275 I kraft Gesetzes."], ["L und M teilen sich den Schaden je zur Hälfte.", "Falsch. Eine Teilung gibt es nicht."]], "id": "P2-lst2-5"}, {"topic": "lst", "sv": "Händler H schuldet K 10 Kisten Wein (Gattungsschuld, Holschuld). H sondert am Vortag 10 Kisten aus, beschriftet sie mit K’s Namen und teilt K mit, er könne sie morgen abholen. In der Nacht werden die Kisten ohne Verschulden des H gestohlen. K war nicht im Annahmeverzug.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["H muss erneut 10 Kisten liefern, weil er Gattungsware schuldet.", "Falsch. Mit Aussonderung und Benachrichtigung hat sich die Holschuld konkretisiert (§ 243 II)."], ["H ist frei, verliert aber den Kaufpreisanspruch (§§ 275 I, 326 I).", "Richtig. Konkretisierung, aber kein Gefahrübergang hinsichtlich des Preises. (§§ 243 II, 275 I, 326 I 1)"], ["H ist frei und behält den Kaufpreisanspruch, weil die Gefahr mit der Konkretisierung übergeht.", "Falsch. Die Preisgefahr bleibt bei H, solange K nicht im Annahmeverzug ist (§ 326 I 1)."], ["H muss Schadensersatz leisten, weil er die Kisten nicht bewacht hat.", "Falsch. Ein Verschulden des H liegt nicht vor."], ["K muss zahlen, weil er die Kisten nicht noch am selben Abend abgeholt hat.", "Falsch. Abholung war für den nächsten Tag vereinbart; kein Annahmeverzug."], ["Die Konkretisierung tritt bei der Holschuld erst mit der Abholung ein.", "Falsch. Aussonderung und Benachrichtigung genügen."]], "id": "P2-lst2-6"}, {"topic": "lst", "sv": "Brauerei B und Gastwirt G vereinbaren 2024 Bierlieferungen für fünf Jahre zu einem Festpreis. 2026 verdreifachen sich die Energiekosten durch eine unvorhersehbare Krise; B würde ohne Anpassung in die Insolvenz geraten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["B kann sofort vom Vertrag zurücktreten.", "Falsch. Vorrang hat die Anpassung (§ 313 III)."], ["B ist nach § 275 II von der Lieferpflicht frei.", "Falsch. Wirtschaftliche Erschwerung fällt unter § 313."], ["B kann eine Anpassung des Preises verlangen, wenn ihm das Festhalten unzumutbar ist (§ 313 I).", "Richtig. Schwerwiegende, unvorhersehbare Änderung."], ["B muss zum Festpreis weiterliefern, weil Preisrisiken stets beim Lieferanten liegen.", "Falsch. „Stets“: Bei existenzbedrohender, unvorhersehbarer Änderung kann § 313 greifen."], ["B kann den Preis einseitig auf das neue Niveau erhöhen.", "Falsch. § 313 gibt einen Anspruch auf Anpassung, kein einseitiges Recht."], ["G kann wegen der Krise eine Senkung des Preises verlangen.", "Falsch. Die Änderung belastet B, nicht G."]], "id": "P2-lst2-7"}, {"topic": "lst", "sv": "K mietet für seine Hochzeitsfeier am 1. August den Festsaal des V. Am 20. Juli brennt der Saal ab, V trifft kein Verschulden. K hatte bereits 3.000 € angezahlt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["V ist frei, K muss nichts zahlen und bekommt die 3.000 € zurück (§§ 275 I, 326 I, IV).", "Richtig. Unmöglichkeit ohne Vertretenmüssen; Rückforderung nach § 326 IV."], ["K muss die Miete zahlen, weil der Brand nicht in seiner Sphäre lag, aber auch nicht in V’s.", "Falsch. Die Gegenleistung entfällt (§ 326 I 1)."], ["V muss einen gleichwertigen Saal besorgen.", "Falsch. Der bestimmte Saal ist geschuldet; die Leistung ist unmöglich."], ["K bekommt die 3.000 € nur, wenn er vorher zurücktritt.", "Falsch. § 326 IV gibt die Rückforderung kraft Gesetzes."], ["V schuldet zusätzlich Schadensersatz für die abgesagte Feier.", "Falsch. V hat den Brand nicht zu vertreten."], ["K bekommt nur die Hälfte zurück, weil der Brand höhere Gewalt war.", "Falsch. Eine Teilung gibt es nicht."]], "id": "P2-lst2-8"}, {"topic": "lst", "sv": "K kauft bei V einen gebrauchten Traktor. Vor der Übergabe beschädigt V’s Mitarbeiter den Traktor fahrlässig so schwer, dass er nicht mehr zu reparieren ist. K hatte bereits einen Anhänger für 1.500 € gekauft, der nur zu diesem Traktor passt.", "q": "Was kann K wegen des Anhängers verlangen?", "c": 4, "o": [["Nichts, weil der Anhänger nicht Gegenstand des Vertrags mit V war.", "Falsch. Vergebliche Aufwendungen sind nach § 284 ersatzfähig."], ["Die 1.500 € zusätzlich zum vollen Schadensersatz statt der Leistung.", "Falsch. § 284 gilt „anstelle“ des Schadensersatzes statt der Leistung."], ["Die 1.500 € nur, wenn V selbst den Traktor beschädigt hat.", "Falsch. Das Verschulden des Mitarbeiters wird zugerechnet (§ 278)."], ["Die 1.500 € nur nach erfolgloser Fristsetzung.", "Falsch. Bei Unmöglichkeit ist eine Frist sinnlos (§ 283)."], ["Die 1.500 € als vergebliche Aufwendungen (§ 284).", "Richtig. Unmöglichkeit, von V zu vertreten. (§§ 284, 283, 278)"], ["Die 1.500 € als Rückzahlung nach § 346.", "Falsch. § 346 betrifft nur die zwischen K und V ausgetauschten Leistungen."]], "id": "P2-lst2-9"}, {"topic": "lst", "sv": "V verkauft K ein Auto Zug um Zug gegen Zahlung. Bei der Übergabe will K erst zahlen, nachdem V ihm den Fahrzeugbrief gegeben hat; V will umgekehrt erst das Geld.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["K muss zuerst zahlen, weil der Käufer immer vorleistungspflichtig ist.", "Falsch. Beim gegenseitigen Vertrag wird Zug um Zug geleistet (§ 320)."], ["V muss zuerst liefern, weil er die Ware hat.", "Falsch. Eine Vorleistungspflicht ist nicht vereinbart."], ["Der Vertrag ist aufgehoben, weil sich die Parteien über die Reihenfolge nicht einigen.", "Falsch. Die Reihenfolge regelt das Gesetz."], ["Jeder kann die Leistung bis zur Gegenleistung verweigern; Zug um Zug (§ 320).", "Richtig. Einrede des nicht erfüllten Vertrags. (§§ 320, 322)"], ["K kann vom Vertrag zurücktreten, weil V den Brief zurückhält.", "Falsch. V darf zurückhalten, solange K nicht zahlt."], ["V ist in Verzug, weil er den Brief nicht sofort übergibt.", "Falsch. Wer die Einrede des § 320 hat, gerät nicht in Verzug."]], "id": "P2-lst2-10"}, {"topic": "lst", "sv": "Handwerkerin H soll bei K ein Bad sanieren. Nach der Hälfte der Arbeiten fragt H, ob K zahlungsfähig sei; K bestätigt das. Kurz darauf erfährt H, dass gegen K zahlreiche Vollstreckungen laufen und K seine Lieferanten nicht bezahlt. H soll vorleisten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["H muss weiterarbeiten, weil sie vorleistungspflichtig ist.", "Falsch. Bei Gefährdung der Gegenleistung gibt § 321 eine Unsicherheitseinrede."], ["H kann sofort ohne Weiteres vom Vertrag zurücktreten.", "Falsch. Zuerst kann sie verweigern und eine Frist für Zug-um-Zug-Leistung oder Sicherheit setzen (§ 321 II)."], ["H kann den Vertrag wegen arglistiger Täuschung anfechten und den vollen Werklohn verlangen.", "Falsch. Nach Anfechtung entfällt der Werklohnanspruch; die Rechtsfolge passt nicht."], ["H kann Schadensersatz verlangen, weil K zahlungsunfähig ist.", "Falsch. Es fehlt bisher an einer Pflichtverletzung durch Nichtzahlung."], ["H muss die Arbeiten fortsetzen und kann später die Vollstreckung betreiben.", "Falsch. § 321 schützt die Vorleistende gerade davor."], ["H kann ihre Leistung verweigern, bis K zahlt oder Sicherheit leistet (§ 321 I).", "Richtig. Unsicherheitseinrede bei mangelnder Leistungsfähigkeit."]], "id": "P2-lst2-11"}, {"topic": "lst", "sv": "Fahrradhändler F verkauft dem K ein Rad. F’s Lieferant liefert verspätet, sodass F seinerseits verspätet an K liefert. K verlangt Ersatz der Taxikosten für die Zeit des Verzugs.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["F haftet nicht, weil der Lieferant die Verspätung verursacht hat und dessen Erfüllungsgehilfe ist.", "Falsch. Der Lieferant ist gerade nicht Erfüllungsgehilfe des Verkäufers."], ["F haftet nur, wenn er den Lieferanten nachlässig ausgewählt hat (§ 831).", "Falsch. Im Vertrag gilt § 276; beim Gattungskauf trägt F das Beschaffungsrisiko."], ["F haftet nicht, weil Taxikosten kein ersatzfähiger Schaden sind.", "Falsch. Sie sind typischer Verzögerungsschaden, wenn sie angemessen sind."], ["F haftet, weil er beim Gattungskauf das Beschaffungsrisiko übernommen hat.", "Richtig. Vertretenmüssen über das Beschaffungsrisiko. (§§ 280 I, II, 286, 276 I)"], ["F haftet, aber nur auf Zinsen, weil Verzug nur Geldschulden betrifft.", "Falsch. Verzug gibt es bei jeder Leistung."], ["F haftet nicht, weil K nicht zurückgetreten ist.", "Falsch. Der Verzögerungsschaden besteht neben der Leistung."]], "id": "P2-lst2-12"}, {"topic": "lst", "sv": "V verkauft K einen Rasenmäher. Im Kaufvertrag steht: „Lieferung, sobald die Ware eintrifft.“ Nach acht Wochen ist noch nichts geliefert. K mahnt nicht, sondern bestellt woanders.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["V ist in Verzug, weil acht Wochen offensichtlich zu lang sind.", "Falsch. Ohne kalendermäßige Bestimmung braucht es eine Mahnung (§ 286 I)."], ["V ist nicht in Verzug, weil K weder gemahnt noch eine Frist gesetzt hat.", "Richtig. Keine Ausnahme nach § 286 II."], ["V ist in Verzug, weil die Leistungszeit nach dem Kalender bestimmt ist.", "Falsch. „Sobald die Ware eintrifft“ ist keine kalendermäßige Bestimmung."], ["V ist in Verzug, weil 30 Tage seit Vertragsschluss vergangen sind (§ 286 III).", "Falsch. § 286 III gilt nur für Entgeltforderungen."], ["K kann wegen der Verspätung ohne Weiteres zurücktreten.", "Falsch. Der Rücktritt setzt eine erfolglose Frist voraus (§ 323 I)."], ["V ist in Verzug, weil er eine Gattungsschuld hat und das Beschaffungsrisiko trägt.", "Falsch. Das Beschaffungsrisiko betrifft das Vertretenmüssen, nicht die Mahnung."]], "id": "P2-lst2-13"}, {"topic": "lst", "sv": "Vermieter V verpflichtet sich, dem Mieter M die Wohnung ab 1. Mai zu überlassen. Der Vormieter zieht nicht aus. M muss vier Wochen ins Hotel und verlangt die Kosten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Die Hotelkosten als Verzögerungsschaden, wenn V dies zu vertreten hat.", "Richtig. Kalendermäßige Leistungszeit, Vertretenmüssen wird vermutet. (§§ 280 I, II, 286)"], ["V haftet nicht, weil der Vormieter die Verzögerung verursacht hat.", "Falsch. V hat die rechtzeitige Überlassung zugesagt; das Risiko liegt bei ihm."], ["M kann nur die Miete für Mai kürzen, Hotelkosten bekommt er nicht.", "Falsch. Daneben kommt Schadensersatz in Betracht."], ["V haftet nur, wenn M ihn vor dem 1. Mai gemahnt hat.", "Falsch. Die Mahnung ist bei kalendermäßiger Bestimmung entbehrlich."], ["M muss die Hotelkosten selbst tragen, weil Mietverträge keinen Verzug kennen.", "Falsch. Auch im Mietrecht gelten die allgemeinen Regeln."], ["V haftet, aber nur auf Rückzahlung einer Kaution.", "Falsch. Die Hotelkosten sind ersatzfähiger Schaden."]], "id": "P2-lst2-14"}, {"topic": "lst", "sv": "K bestellt beim Möbelhaus M eine Küche, Lieferung am 15. März. Am 15. März liefert M nicht. K setzt eine angemessene Frist bis 31. März, die erfolglos abläuft. Am 2. April erklärt K: „Ich will jetzt Schadensersatz statt der Leistung.“ Am 5. April bietet M die Küche doch noch an.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["K muss die Küche abnehmen, weil M noch liefern kann.", "Falsch. § 281 IV schließt den Leistungsanspruch aus."], ["K muss die Küche nicht mehr abnehmen; der Leistungsanspruch ist ausgeschlossen.", "Richtig. Mit dem Verlangen erlischt der Erfüllungsanspruch. (§ 281 IV)"], ["K muss die Küche abnehmen, weil er noch nicht zurückgetreten ist.", "Falsch. Schon das Verlangen von Schadensersatz statt der Leistung beendet den Leistungsanspruch."], ["K kann frei wählen, ob er die Küche jetzt doch noch nimmt; M muss dann liefern.", "Falsch. Nach § 281 IV kann K nicht mehr Erfüllung verlangen."], ["Der Vertrag ist mit Fristablauf am 31. März automatisch erloschen.", "Falsch. Der Fristablauf allein beendet nichts."], ["K muss die Küche abnehmen, kann aber Verzugszinsen auf den Kaufpreis verlangen.", "Falsch. Verzugszinsen setzt eine Geldschuld des M voraus."]], "id": "P2-lst3-0"}, {"topic": "lst", "sv": "Verkäufer V liefert dem Kaufmann K vertragsgemäß eine Maschine. Bei der Aufstellung beschädigt V’s Monteur fahrlässig den Hallenboden des K (Schaden 2.000 €). Die Maschine selbst ist einwandfrei.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["K hat keinen Anspruch gegen V, weil die Maschine mangelfrei ist.", "Falsch. Es geht um eine Schutzpflichtverletzung, nicht um einen Mangel."], ["K hat einen Anspruch erst nach erfolgloser Fristsetzung zur Reparatur des Bodens.", "Falsch. Schadensersatz neben der Leistung braucht keine Frist."], ["K hat nur einen Anspruch gegen den Monteur aus § 823 I.", "Falsch. V haftet daneben vertraglich (§ 278)."], ["K kann vom Kaufvertrag zurücktreten, weil V eine Pflicht verletzt hat.", "Falsch. Ein Rücktritt nach § 324 setzt Unzumutbarkeit voraus; ein einmaliger Bodenschaden genügt nicht."], ["K hat keinen Anspruch, weil V sich nach § 831 entlasten kann.", "Falsch. Im Vertrag gilt § 278 ohne Entlastungsmöglichkeit."], ["K kann von V 2.000 € aus §§ 280 I, 241 II, 278 verlangen.", "Richtig. Verletzung einer Rücksichtnahmepflicht durch den Erfüllungsgehilfen."]], "id": "P2-lst3-1"}, {"topic": "lst", "sv": "K lässt sein Auto in die Werkstatt W bringen. Nach der Reparatur stellt W das Auto über Nacht unverschlossen auf die Straße; es wird gestohlen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["W haftet nicht, weil der Dieb den Schaden verursacht hat.", "Falsch. W hat eine eigene Obhutspflicht verletzt."], ["W haftet nur aus § 823 I, weil der Diebstahl außerhalb der Werkstatt geschah.", "Falsch. Daneben besteht eine vertragliche Haftung."], ["W haftet nur, wenn K ausdrücklich eine sichere Verwahrung vereinbart hatte.", "Falsch. Die Obhutspflicht folgt schon aus § 241 II."], ["W haftet nur auf den halben Wert, weil der Dieb hauptverantwortlich ist.", "Falsch. W haftet voll; der Dieb haftet daneben."], ["W haftet aus §§ 280 I, 241 II wegen fahrlässiger Verletzung der Obhutspflicht.", "Richtig. Schutzpflichtverletzung im Werkvertrag."], ["W haftet nicht, weil die Reparatur ordnungsgemäß war und der Vertrag damit erfüllt ist.", "Falsch. Bis zur Rückgabe bestehen Obhutspflichten."]], "id": "P2-lst3-2"}, {"topic": "lst", "sv": "Arbeitgeber A und Arbeitnehmer B schließen einen Arbeitsvertrag. B fehlt wiederholt unentschuldigt und wurde zweimal abgemahnt. A will das Arbeitsverhältnis beenden.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["A kann nach § 323 vom Arbeitsvertrag zurücktreten.", "Falsch. Bei Dauerschuldverhältnissen tritt die Kündigung an die Stelle des Rücktritts."], ["A kann den Vertrag wegen arglistiger Täuschung anfechten.", "Falsch. Es gab keine Täuschung bei Vertragsschluss."], ["A kann nur nach § 313 eine Anpassung des Lohns verlangen.", "Falsch. § 313 passt nicht; es geht um Vertragsverletzungen."], ["A kann nach erfolgloser Abmahnung aus wichtigem Grund kündigen.", "Richtig. Dauerschuldverhältnis, Abmahnung erfolgt. (§§ 314, 626)"], ["A muss B zuerst eine Nachfrist zur Arbeitsleistung setzen (§ 281).", "Falsch. Die Abmahnung ersetzt die Fristsetzung (§ 314 II)."], ["A kann das Arbeitsverhältnis nur zum Jahresende beenden.", "Falsch. Die außerordentliche Kündigung wirkt sofort."]], "id": "P2-lst3-3"}, {"topic": "lst", "sv": "K schuldet V aus einem Kaufvertrag 1.000 €. V schuldet K aus einem anderen Geschäft 400 €, die schon fällig sind. V verlangt 1.000 €; K erklärt, er rechne mit seinen 400 € auf.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Die Forderung des V besteht nur noch in Höhe von 600 € (§§ 387, 389).", "Richtig. Gegenseitig, gleichartig, fällig."], ["Die Aufrechnung ist unzulässig, weil die Forderungen aus verschiedenen Verträgen stammen.", "Falsch. Konnexität ist keine Voraussetzung der Aufrechnung."], ["Die Aufrechnung ist nur wirksam, wenn V ihr zustimmt.", "Falsch. Sie ist eine einseitige Erklärung (§ 388)."], ["Die Aufrechnung bringt beide Forderungen vollständig zum Erlöschen.", "Falsch. Nur soweit sie sich decken (§ 389)."], ["K muss zuerst die 1.000 € zahlen und kann dann die 400 € einfordern.", "Falsch. Durch die Aufrechnung erlischt die Forderung teilweise."], ["Die Aufrechnung wirkt erst ab der Zahlung der restlichen 600 €.", "Falsch. Sie wirkt auf den Zeitpunkt der Aufrechnungslage zurück (§ 389)."]], "id": "P2-lst3-4"}, {"topic": "lst", "sv": "K schuldet V 500 €. Statt zu zahlen, übergibt K dem V mit dessen Einverständnis einen Scheck über 500 € „erfüllungshalber“. Der Scheck platzt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Die Schuld ist mit der Übergabe des Schecks erloschen.", "Falsch. Erfüllungshalber heißt: Erlöschen erst mit Einlösung."], ["V hat nur noch Ansprüche aus dem Scheck, nicht mehr aus dem Kaufvertrag.", "Falsch. Die ursprüngliche Forderung bleibt bestehen."], ["Die Kaufpreisforderung besteht fort; der Scheck wurde nur erfüllungshalber gegeben.", "Richtig. Erfüllung erst mit Einlösung (§ 364 II im Zweifel)."], ["V muss K den Scheck zurückgeben und hat dann keine Rechte mehr.", "Falsch. V kann weiterhin Zahlung verlangen."], ["Die Schuld ist erloschen; K haftet wie ein Verkäufer für den geplatzten Scheck (§ 365).", "Falsch. § 365 betrifft die Leistung an Erfüllungs statt."], ["K muss nur die Hälfte zahlen, weil V das Risiko des Schecks übernommen hat.", "Falsch. Das Risiko des Scheckausfalls trägt nicht V."]], "id": "P2-lst3-5"}, {"topic": "lst", "sv": "Unternehmer K soll dem Großhändler V für eine Warenlieferung am 1. Juni 1.000 € zahlen. K überweist am 1. Juni, das Geld wird dem Konto des V aber erst am 4. Juni gutgeschrieben.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["K ist nicht in Verzug, weil er rechtzeitig überwiesen hat und es auf die Leistungshandlung ankommt.", "Falsch. Nach dem EuGH und dem BGH kommt es bei Geldschulden auf die Gutschrift an."], ["K ist erst nach einer Mahnung in Verzug.", "Falsch. Bei kalendermäßig bestimmter Leistungszeit ist keine Mahnung nötig."], ["K ist ab dem 2. Juni in Verzug, weil das Geld erst am 4. Juni gutgeschrieben wurde.", "Richtig. Rechtzeitig ist die Zahlung erst mit Gutschrift beim Gläubiger."], ["K ist nicht in Verzug, weil die Verspätung allein die Bank betrifft.", "Falsch. Das Verzögerungsrisiko der Überweisung trägt der Schuldner."], ["K ist nie in Verzug, weil Geldschulden Schickschulden sind.", "Falsch. Seit der EuGH-Rechtsprechung kommt es auf den Eingang an."], ["K ist in Verzug, aber nur, wenn er die Bank schlecht ausgewählt hat.", "Falsch. Auf Auswahlverschulden kommt es nicht an; geschuldet ist der rechtzeitige Eingang."]], "id": "P2-lst3-6"}, {"topic": "lst", "sv": "V hat K einen Laptop verkauft und soll ihn am 10. Mai liefern. Am 8. Mai teilt V mit, der Laptop sei bei ihm gestohlen worden; V trifft kein Verschulden. K hatte den Kaufpreis von 1.000 € schon gezahlt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["V muss einen anderen gleichwertigen Laptop beschaffen.", "Falsch. Es ging um einen bestimmten Laptop (Stückschuld)."], ["K bekommt nichts zurück, weil die Gefahr mit der Zahlung übergegangen ist.", "Falsch. Die Gefahr geht erst mit Übergabe über (§ 446)."], ["K bekommt das Geld nur zurück, wenn er zuvor zurücktritt.", "Falsch. § 326 IV gibt den Anspruch kraft Gesetzes."], ["V schuldet zusätzlich Schadensersatz statt der Leistung.", "Falsch. V hat den Diebstahl nicht zu vertreten."], ["K bekommt nur die Hälfte zurück, weil der Diebstahl höhere Gewalt war.", "Falsch. Eine Teilung gibt es nicht."], ["V ist frei; K kann die 1.000 € zurückverlangen (§ 326 IV).", "Richtig. Unmöglichkeit ohne Vertretenmüssen, Rückforderung der Vorleistung. (§§ 275 I, 326 I, IV, 346)"]], "id": "P2-lst3-7"}, {"topic": "lst", "sv": "Maler M streicht bei Kunde K die Fassade. K hatte zugesagt, den Garten freizuräumen, damit das Gerüst aufgestellt werden kann. K tut das nicht; M kann deshalb drei Tage nicht arbeiten und hat Mehrkosten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["M kann von K Schadensersatz nach § 280 I verlangen, weil K seine Pflicht zur Mitwirkung verletzt hat.", "Falsch. Die Mitwirkung des Bestellers ist grundsätzlich nur eine Obliegenheit."], ["M hat keine Ansprüche, weil er den Garten selbst hätte räumen müssen.", "Falsch. Das war Sache des K."], ["M kann vom Vertrag sofort zurücktreten.", "Falsch. Dafür fehlt die Grundlage; § 643 verlangt zunächst eine Frist."], ["K ist in Annahmeverzug; M kann Entschädigung verlangen.", "Richtig. Mitwirkungsobliegenheit beim Werkvertrag. (§ 642)"], ["M kann von K Verzugszinsen auf den Werklohn verlangen.", "Falsch. Der Werklohn ist noch nicht fällig."], ["M muss die Arbeit ohne Ausgleich fortsetzen, weil der Besteller frei entscheiden darf.", "Falsch. § 642 gibt eine Entschädigung."]], "id": "P2-lst3-8"}, {"topic": "lst", "sv": "Kunde K kauft beim Händler H ein Smartphone. Bei Vertragsschluss sagt H: „Lieferung in zwei Wochen.“ Danach erfährt H, dass das Modell nicht mehr produziert wird und auch sonst nirgends erhältlich ist. H hatte das bei Vertragsschluss fahrlässig nicht geprüft, obwohl es bereits öffentlich bekannt war.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["Der Vertrag ist nichtig, weil die Leistung schon bei Vertragsschluss unmöglich war.", "Falsch. § 311a I: Der Vertrag bleibt wirksam."], ["K hat keinen Anspruch, weil H die Einstellung nicht kannte.", "Falsch. Fahrlässige Unkenntnis genügt (§ 311a II 2)."], ["K kann nur zurücktreten, Schadensersatz scheidet bei anfänglicher Unmöglichkeit aus.", "Falsch. § 311a II gewährt Schadensersatz."], ["H muss ein Nachfolgemodell liefern.", "Falsch. Geschuldet war das bestimmte Modell; ein anderes kann K nicht verlangen."], ["K kann Schadensersatz statt der Leistung verlangen, weil H das Hindernis kennen musste.", "Richtig. Anfängliche Unmöglichkeit, fahrlässige Unkenntnis. (§ 311a II)"], ["K kann Schadensersatz nur nach §§ 280, 283 verlangen.", "Falsch. Bei anfänglicher Unmöglichkeit ist § 311a II die Anspruchsgrundlage."]], "id": "P2-lst3-9"}, {"topic": "lst", "sv": "V verkauft K eine wertvolle Vase. Bei der Übergabe stößt K sie aus Unachtsamkeit selbst vom Tisch, bevor V sie ihm überreichen kann; sie zerbricht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["V ist frei und behält den Kaufpreis, weil K den Untergang allein verantwortet.", "Richtig. Verantwortlichkeit des Gläubigers. (§ 326 II 1 Alt. 1)"], ["K muss nicht zahlen, weil V noch nicht übergeben hatte (§ 326 I 1).", "Falsch. Der Gläubiger ist für den Untergang verantwortlich (§ 326 II 1 Alt. 1)."], ["V muss eine gleichwertige Vase liefern.", "Falsch. Stückschuld; die Leistung ist unmöglich."], ["K muss nur die Hälfte zahlen, weil beide am Tisch standen.", "Falsch. K allein ist verantwortlich."], ["K muss zahlen, kann aber V Schadensersatz für die Vase entgegenhalten.", "Falsch. V hat nichts verschuldet."], ["Der Vertrag ist aufgehoben, weil die Vase vor Übergabe zerstört wurde.", "Falsch. Der Vertrag bleibt; nur die Leistungspflicht entfällt."]], "id": "P2-lst3-10"}, {"topic": "lst", "sv": "Elektriker E soll im Haus des K Leitungen verlegen, Fertigstellung bis 30. September. E arbeitet so langsam, dass schon Anfang September offensichtlich ist, dass er nicht vor Dezember fertig wird.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["K muss bis zum 30. September warten, bevor er irgendetwas unternehmen kann.", "Falsch. § 323 IV erlaubt den Rücktritt schon vor Fälligkeit."], ["K kann bereits vor Fälligkeit am 30. September zurücktreten (§ 323 IV).", "Richtig. Rücktritt vor Fälligkeit."], ["K kann sofort ohne Weiteres Schadensersatz statt der Leistung verlangen.", "Falsch. Schadensersatz setzt Vertretenmüssen und grundsätzlich Fristablauf nach Fälligkeit voraus."], ["K kann nur nach § 313 eine Anpassung des Termins verlangen.", "Falsch. Es geht um eine Pflichtverletzung, nicht um die Geschäftsgrundlage."], ["K kann vor Fälligkeit nur zurücktreten, wenn E das Zurückbleiben verschuldet hat.", "Falsch. Der Rücktritt ist verschuldensunabhängig."], ["K kann erst zurücktreten, wenn E auch eine Nachfrist bis Dezember verstreichen lässt.", "Falsch. § 323 IV verlangt keine Nachfrist."]], "id": "P2-lst3-11"}, {"topic": "lst", "sv": "K hat V nach einem erheblichen Mangel erfolglos eine Frist zur Nacherfüllung gesetzt. Danach schreibt K dem V per WhatsApp: „Ich trete vom Kaufvertrag zurück, holen Sie den Wagen ab.“ V meint, das sei unwirksam.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Der Rücktritt ist unwirksam, weil er schriftlich mit Unterschrift erklärt werden muss.", "Falsch. Der Rücktritt ist formfrei (§ 349)."], ["Der Rücktritt ist erst wirksam, wenn V ihn annimmt.", "Falsch. Er ist ein einseitiges Gestaltungsrecht."], ["Der Rücktritt ist wirksam; er erfolgt formlos durch Erklärung (§ 349).", "Richtig. Zugang der WhatsApp-Nachricht genügt."], ["Der Rücktritt ist erst wirksam, wenn ein Gericht ihn bestätigt.", "Falsch. Eine gerichtliche Bestätigung ist nicht nötig."], ["Der Rücktritt ist unwirksam, weil K den Wagen nicht gleichzeitig zurückgegeben hat.", "Falsch. Die Rückgabe ist Rechtsfolge, keine Wirksamkeitsvoraussetzung."], ["Der Rücktritt ist unwirksam, weil K zuerst mindern muss.", "Falsch. Minderung ist eine Alternative, keine Voraussetzung."]], "id": "P2-lst3-12"}, {"topic": "lst", "sv": "K und V vereinbaren, dass V dem K am 1. Juni 100 Liter Heizöl liefert. V liefert erst am 15. Juni. In der Zwischenzeit steigt der Heizölpreis; K musste am 5. Juni teurer bei einem anderen Händler kaufen, ohne V eine Frist gesetzt zu haben. V hat die Verspätung zu vertreten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["K bekommt die Mehrkosten nicht, weil er keine Frist gesetzt hat.", "Richtig. Deckungskauf ohne Fristsetzung. (§ 281 I)"], ["K bekommt die Mehrkosten als Verzögerungsschaden ohne Frist.", "Falsch. Mehrkosten eines Deckungskaufs sind Schadensersatz statt der Leistung."], ["K bekommt die Mehrkosten, weil V in Verzug war.", "Falsch. Verzug allein genügt für Schadensersatz statt der Leistung nicht."], ["K muss das Öl vom 15. Juni nicht abnehmen, weil er schon anderswo gekauft hat.", "Falsch. Ohne Fristablauf besteht der Erfüllungsanspruch fort."], ["K bekommt die Mehrkosten, weil bei Heizöl stets ein Fixgeschäft vorliegt.", "Falsch. Ein Fixgeschäft ist nicht ersichtlich."], ["K bekommt die Mehrkosten zur Hälfte (§ 254).", "Falsch. Der Anspruch scheitert schon an der Frist."]], "id": "P2-lst3-13"}, {"topic": "lst", "sv": "V schuldet K ein bestimmtes Pferd. Nach Vertragsschluss verkauft V das Pferd an D und übergibt es ihm. D ist nicht bereit, es herauszugeben.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["V muss das Pferd von D zurückkaufen, koste es, was es wolle.", "Falsch. Wenn D nicht bereit ist, ist V die Leistung unmöglich (§ 275 I, Unvermögen)."], ["K kann das Pferd von D herausverlangen, weil er zuerst gekauft hat.", "Falsch. Ein Kaufvertrag wirkt nur zwischen den Parteien."], ["D muss K Schadensersatz leisten, weil er in einen fremden Vertrag eingegriffen hat.", "Falsch. Eine Forderung ist kein absolutes Recht im Sinne des § 823 I."], ["Der zweite Kaufvertrag mit D ist nichtig, weil V schon an K verkauft hatte.", "Falsch. Auch der Doppelverkauf ist wirksam."], ["K kann nur zurücktreten, Schadensersatz scheidet aus, weil D das Pferd hat.", "Falsch. V hat die Unmöglichkeit zu vertreten."], ["V ist die Leistung unmöglich; K kann Schadensersatz statt der Leistung verlangen.", "Richtig. Subjektive Unmöglichkeit, von V zu vertreten. (§§ 275 I, 280 I, III, 283)"]], "id": "P2-lst3-14"}];
L.forEach(q=>{ if(!W.some(x=>x.id===q.id)) W.push(q); });
window.dispatchEvent(new Event('wpr-data'));
})();
